-- AI-assisted synthetic copy of the course table layout for isolated SQL verification only.
CREATE TABLE dbo.Genre(genreID int PRIMARY KEY,Name nvarchar(255));
CREATE TABLE dbo.BookGenre(ID int PRIMARY KEY,Name nvarchar(255));
CREATE TABLE dbo.MovieGenre(ID int PRIMARY KEY,Name nvarchar(255));
CREATE TABLE dbo.GameGenre(ID int PRIMARY KEY,Name nvarchar(255));
CREATE TABLE dbo.[User](UserID int IDENTITY,UserName nvarchar(50) PRIMARY KEY,Email nvarchar(255),Name nvarchar(255),isAdmin bit,Salt varchar(32),HashPW varchar(64));
CREATE TABLE dbo.Patrons(UserID int IDENTITY PRIMARY KEY,Email nvarchar(255),Name nvarchar(255),Salt varchar(32),HashPW varchar(64));
CREATE TABLE dbo.Product(ID int IDENTITY PRIMARY KEY,Name nvarchar(255),Author nvarchar(255),Description nvarchar(max),Genre int REFERENCES dbo.Genre(genreID),SubGenre int,Published date,LastUpdatedBy nvarchar(50) REFERENCES dbo.[User](UserName),LastUpdated datetime2);
CREATE TABLE dbo.Source(sourceid int PRIMARY KEY,Source_name nvarchar(max),Genre int);
CREATE TABLE dbo.Stocktake(ItemId int IDENTITY PRIMARY KEY,SourceId int REFERENCES dbo.Source(sourceid),ProductId int REFERENCES dbo.Product(ID),Quantity int,Price float);
CREATE TABLE dbo.[TO](customerID int IDENTITY PRIMARY KEY,PatronId int REFERENCES dbo.Patrons(UserID),Email nvarchar(255) NOT NULL,PhoneNumber nvarchar(50),StreetAddress nvarchar(255),PostCode int,Suburb nvarchar(50),State nvarchar(50),CardNumber nvarchar(50),CardOwner nvarchar(50),Expiry varchar(5),CVV int);
CREATE TABLE dbo.Orders(OrderID int IDENTITY PRIMARY KEY,customer int REFERENCES dbo.[TO](customerID),StreetAddress nvarchar(255),PostCode int,Suburb nvarchar(255),State nvarchar(50));
CREATE TABLE dbo.ProductsInOrders(OrderId int REFERENCES dbo.Orders(OrderID),produktId int REFERENCES dbo.Stocktake(ItemId),Quantity int);
